-- =====================================================================================
-- Part 2: raw SQL
-- =====================================================================================

-- ---- CHECK constraints ---------------------------------------------------------------
ALTER TABLE "users"
  ADD CONSTRAINT "users_strike_count_check" CHECK ("strike_count" >= 0),
  ADD CONSTRAINT "users_phone_format_check" CHECK ("phone" IS NULL OR "phone" ~ '^\+?[0-9]{10,14}$'),
  ADD CONSTRAINT "users_full_name_length_check" CHECK ("full_name" IS NULL OR char_length("full_name") >= 2);

ALTER TABLE "otp_codes"
  ADD CONSTRAINT "otp_codes_attempts_check" CHECK ("attempts" >= 0);

ALTER TABLE "emergency_contacts"
  ADD CONSTRAINT "emergency_contacts_phone_format_check" CHECK ("phone" IS NULL OR "phone" ~ '^\+?[0-9]{10,14}$');

ALTER TABLE "reports"
  ADD CONSTRAINT "reports_latitude_check" CHECK ("latitude" BETWEEN -90 AND 90),
  ADD CONSTRAINT "reports_longitude_check" CHECK ("longitude" BETWEEN -180 AND 180),
  ADD CONSTRAINT "reports_confirmation_count_check" CHECK ("confirmation_count" >= 0),
  ADD CONSTRAINT "reports_title_length_check" CHECK (char_length("title") BETWEEN 5 AND 80),
  ADD CONSTRAINT "reports_description_length_check" CHECK (char_length("description") BETWEEN 10 AND 1000),
  ADD CONSTRAINT "reports_version_check" CHECK ("version" >= 0);

ALTER TABLE "report_photos"
  ADD CONSTRAINT "report_photos_position_check" CHECK ("position" BETWEEN 0 AND 3),
  ADD CONSTRAINT "report_photos_dimensions_check" CHECK (("width" IS NULL OR "width" > 0) AND ("height" IS NULL OR "height" > 0));

ALTER TABLE "rides"
  ADD CONSTRAINT "rides_source_lat_check" CHECK ("source_lat" BETWEEN -90 AND 90),
  ADD CONSTRAINT "rides_source_lng_check" CHECK ("source_lng" BETWEEN -180 AND 180),
  ADD CONSTRAINT "rides_dest_lat_check" CHECK ("dest_lat" BETWEEN -90 AND 90),
  ADD CONSTRAINT "rides_dest_lng_check" CHECK ("dest_lng" BETWEEN -180 AND 180),
  ADD CONSTRAINT "rides_seats_total_check" CHECK ("seats_total" BETWEEN 1 AND 3),
  ADD CONSTRAINT "rides_seats_taken_check" CHECK ("seats_taken" >= 0 AND "seats_taken" <= "seats_total"),
  ADD CONSTRAINT "rides_estimated_total_fare_check" CHECK ("estimated_total_fare" BETWEEN 10 AND 5000),
  ADD CONSTRAINT "rides_version_check" CHECK ("version" >= 0);

ALTER TABLE "ride_messages"
  ADD CONSTRAINT "ride_messages_body_length_check" CHECK (char_length("body") BETWEEN 1 AND 500);

ALTER TABLE "journeys"
  ADD CONSTRAINT "journeys_dest_lat_check" CHECK ("dest_lat" IS NULL OR "dest_lat" BETWEEN -90 AND 90),
  ADD CONSTRAINT "journeys_dest_lng_check" CHECK ("dest_lng" IS NULL OR "dest_lng" BETWEEN -180 AND 180),
  ADD CONSTRAINT "journeys_extensions_used_check" CHECK ("extensions_used" BETWEEN 0 AND 2),
  ADD CONSTRAINT "journeys_escalation_minutes_check" CHECK ("escalation_minutes" BETWEEN 20 AND 60);

ALTER TABLE "alerts"
  ADD CONSTRAINT "alerts_latitude_check" CHECK ("latitude" BETWEEN -90 AND 90),
  ADD CONSTRAINT "alerts_longitude_check" CHECK ("longitude" BETWEEN -180 AND 180),
  ADD CONSTRAINT "alerts_confirm_count_check" CHECK ("confirm_count" >= 0),
  ADD CONSTRAINT "alerts_dispute_count_check" CHECK ("dispute_count" >= 0),
  ADD CONSTRAINT "alerts_description_length_check" CHECK (char_length("description") BETWEEN 10 AND 500);

ALTER TABLE "alert_subscriptions"
  ADD CONSTRAINT "alert_subscriptions_center_lat_check" CHECK ("center_lat" IS NULL OR "center_lat" BETWEEN -90 AND 90),
  ADD CONSTRAINT "alert_subscriptions_center_lng_check" CHECK ("center_lng" IS NULL OR "center_lng" BETWEEN -180 AND 180),
  ADD CONSTRAINT "alert_subscriptions_radius_km_check" CHECK ("radius_km" BETWEEN 1 AND 10),
  ADD CONSTRAINT "alert_subscriptions_enabled_center_check" CHECK (NOT "enabled" OR ("center_lat" IS NOT NULL AND "center_lng" IS NOT NULL));

ALTER TABLE "user_blocks"
  ADD CONSTRAINT "user_blocks_not_self_check" CHECK ("blocker_id" <> "blocked_id");

ALTER TABLE "idempotency_keys"
  ADD CONSTRAINT "idempotency_keys_response_status_check" CHECK ("response_status" IS NULL OR "response_status" BETWEEN 100 AND 599);

ALTER TABLE "moderation_actions"
  ADD CONSTRAINT "moderation_actions_reason_check" CHECK (char_length("reason") >= 1);

-- ---- One active journey per user (appendix-06 6.2) -----------------------------------
CREATE UNIQUE INDEX "journeys_one_active_per_user" ON "journeys" ("user_id") WHERE "status" IN ('ACTIVE', 'OVERDUE');

-- ---- Audit log is append-only (appendix-06 6.2, Part B6) -----------------------------
-- Updates are always rejected. Deletes are allowed only for rows past the 2-year retention (6.5).
CREATE FUNCTION "moderation_actions_append_only"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'moderation_actions is append-only' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'DELETE' AND OLD."created_at" > now() - interval '2 years' THEN
    RAISE EXCEPTION 'moderation_actions rows are kept for 2 years' USING ERRCODE = 'check_violation';
  END IF;
  RETURN OLD;
END;
$$;

CREATE TRIGGER "moderation_actions_append_only"
  BEFORE UPDATE OR DELETE ON "moderation_actions"
  FOR EACH ROW EXECUTE FUNCTION "moderation_actions_append_only"();
